import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[] positions = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            positions[i] = total;
            total += fs.nextLong();
        }

        if ((total & 1L) != 0) {
            System.out.println("N");
            return;
        }

        HashSet<Long> points = new HashSet<>();
        for (long position : positions) {
            points.add(position);
        }

        long half = total / 2;
        int antipodalPoints = 0;
        for (long position : positions) {
            if (points.contains((position + half) % total)) {
                antipodalPoints++;
            }
        }

        System.out.println(antipodalPoints >= 4 ? "S" : "N");
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
